{
  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret nævner ikke den lægefagligt dokumenterede, individuelle helhedsvurdering af aktuelle symptomer. Det udelader behandling og effekt, restsymptomer/bivirkninger, medvirken, gentagne sygdomsperioder og tilbagefaldsrisiko. Det tilføjer en 'funktionsvurdering'-metode og momenter som uddannelse/arbejde og behov for hjælp, som ikke er støttet. Det indeholder derfor væsentlige juridiske fejl og mangler."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Kun delvist dækket: påvirkning af daglig funktion og delvist varighed. Mangler lægefagligt dokumenteret grundlag, relevant behandling og effekt, restsymptomer/bivirkninger, rimelig medvirken, gentagne sygdomsperioder og tilbagefaldsrisiko."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret forsøger at besvare, hvad Udbetaling Danmark lægger vægt på ved sværhedsgraden, og er ikke irrelevant fyld. Indholdet er dog delvist forkert."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen kilde, hverken lov, bekendtgørelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer en 'særlig vurderingsmetode kaldet funktionsvurdering', der omfatter fysisk, psykisk og social funktionsevne, uden støtte i materialet. Det tilføjer også momenter som mulighed for uddannelse/arbejde, behov for hjælp og støtte, smerter/træthed som selvstændige vurderingspunkter og en påstand om, at UDK 'altid' vurderer fair."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret gør ikke tydeligt, at momenterne er eksempler ('f.eks.') i en samlet vurdering på lægefagligt dokumenteret grundlag. Listen fremstår som en fast opregning. Der nævnes kun, at vurderingen er individuel."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt konsistent: en liste over momenter og en afsluttende bemærkning om individuel vurdering. Der er ingen indre modsigelser, selv om indholdet er mangelfuldt."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret præsenterer momenterne som faste kriterier ('lægger vægt på følgende'), ikke som illustrative eksempler. Det hævder, at UDK 'bruger' en særlig metode og 'altid' søger en fair vurdering. Det gør vejledningens eksemplificerende formuleringer mere absolutte."}
  },
  "xhaile_coverage": {
    "A14": {"label": "no", "reason": "Svaret nævner ikke, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret, eller at vurderingen bygger på lægefaglige oplysninger/journaler. Det dækker heller ikke behandling, restsymptomer, sygdomshistorik eller styrelsens vurdering af 'meget betydelige begrænsninger'. Kun påvirkning af daglig funktion og varighed berøres løst."}
  },
  "overall_notes": "Svaret er generisk og uden kildehenvisninger. Det rammer kun delvist rubrikken (daglig funktion, varighed). Det udelader centrale elementer som lægefaglig dokumentation, behandling og effekt, restsymptomer, medvirken og tilbagefald, og det tilføjer ustøttede elementer som 'funktionsvurdering' og arbejds-/uddannelsesevne som selvstændigt moment."
}

